# Read output
with open('outputs/t06_stop_service_intensity.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    rows = list(reader)

# Verify RFC 4180 compliance
print("Checking RFC 4180 compliance:")
errors = []

for i, row in enumerate(rows):
    # Check field count
    if len(row) != 8:
        errors.append(f"Row {i}: field count mismatch - expected 8, got {len(row)}")

    # Check for fields with commas, quotes, or newlines
    for j, field in enumerate(row):
        if ',' in field or '"' in field or '\n' in field or '\r' in field:
            errors.append(f"Row {i}, field {j}: {repr(field)} contains special characters")

    # Check that stop_id is an integer
    try:
        int(row['stop_id'])
    except ValueError:
        errors.append(f"Row {i}: stop_id not an integer: {row['stop_id']}")

if errors:
    print("ERRORS FOUND:")
    for error in errors:
        print(f"  {error}")
else:
    print("All rows are valid!")

# Print all rows
print("\nAll rows:")
for row in rows:
    print(f"  stop_id={row['stop_id']}, stop_name={row['stop_name']}, stop_lat={row['stop_lat']}, stop_lon={row['stop_lon']}, n_departures={row['n_departures']}, n_routes={row['n_routes']}, first_departure={row['first_departure']}, last_departure={row['last_departure']}")
